-- Resources content for Sourcework research, Phase C: suggested quotes (CLAUDE.md, "Resources stay in
-- step with the code"). Content only; no schema.

select private.rc_release_guide(
  p_slug => 'sourcework-suggested-quotes',
  p_tool_key => 'transcription',
  p_title => 'Suggested quotes',
  p_summary => 'Have the model pick the clips that would work best on air from a theme’s evidence, then play, trim, accept or reject each one.',
  p_screen_keys => array['sourcework.theme_quotes', 'sourcework.theme'],
  p_sort_order => 22,
  p_version_note => 'First version',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Suggested quotes are clips the model picks from a theme’s evidence for you to play and decide on. A data point is a paraphrase of what someone said; a quote is a literal cut of the recording that would work on air. Nothing becomes an excerpt until you accept it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Ask for quotes"}]},{"type":"paragraph","content":[{"type":"text","text":"Open an accepted theme and choose "},{"type":"text","text":"Suggest quotes","marks":[{"type":"bold"}]},{"type":"text","text":" in the Excerpts panel. It reads the theme’s accepted data points from recordings, supporting and complicating, together with the transcript around them, and takes a minute or two. When it finishes you land on the suggested quotes. A theme that is not accepted yet, has no data points, or has evidence only from documents has no button, and the panel says why."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Decide on each clip"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each card shows how strong the clip is (Strong, Good or Usable), who says it, the words, its length and why it works. A clip marked Complicates comes only from data points that push against the theme; it is there as the counterweight."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Play","marks":[{"type":"bold"}]},{"type":"text","text":" plays the clip as it will cut, from the original audio. Check the words as you listen: the transcript is itself a machine reading of the audio."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Accept","marks":[{"type":"bold"}]},{"type":"text","text":" saves the clip as an ordinary excerpt on its source, linked to the data points it rests on. It then appears in the theme’s Excerpts panel, on the project’s Excerpts tab and in the piece editor."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trim","marks":[{"type":"bold"}]},{"type":"text","text":" opens the start and end with the −250, −50, +50 and +250 buttons. Play again to hear the new cut, then Accept. The words are read again from the transcript for the range you accept."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reject","marks":[{"type":"bold"}]},{"type":"text","text":" hides the clip. It is kept, so the same stretch is not suggested again."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Suggest again"}]},{"type":"paragraph","content":[{"type":"text","text":"Choose "},{"type":"text","text":"Suggest quotes again","marks":[{"type":"bold"}]},{"type":"text","text":" for a fresh look. It replaces the clips still waiting for you and leaves anything you accepted or rejected alone. It does not offer a stretch you already decided on."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clips are only ever taken from the speaker’s own words, one speaker at a time, at sentence edges."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Quote quality guide on the side of the screen is the wording the model works from. Editors maintain it under Research prompts, and can try a draft on a theme before publishing it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choosing quotes sends the theme’s evidence and the transcript around it to an outside service, as extraction does."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Everything here works on a phone: cards stack, and the buttons are larger."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-research-prompts',
  p_tool_key => 'transcription',
  p_title => 'Maintaining the research prompts',
  p_summary => 'For editors: edit the wording, try a draft against the live version, publish and roll back.',
  p_screen_keys => array['sourcework.editors'],
  p_sort_order => 20,
  p_version_note => 'Added the quote quality guide',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Editors maintain the wording the research steps use. You need the Editor role on Sourcework, which an administrator grants on the user’s access screen."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a prompt"}]},{"type":"paragraph","content":[{"type":"text","text":"Open "},{"type":"text","text":"Research prompts","marks":[{"type":"bold"}]},{"type":"text","text":" from the Projects page. Choose Background, Extraction guide, Theme assignment, Theme review or Quote quality guide, edit the text and it saves itself as a draft only you can see. The wording decides what counts as a data point, when a data point belongs in a theme, how a theme should read and what makes a clip work on air; the shape of the answer is fixed by the code, and "},{"type":"text","text":"What the model is given and returns","marks":[{"type":"bold"}]},{"type":"text","text":" shows both."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Try a draft"}]},{"type":"paragraph","content":[{"type":"text","text":"For the extraction guide and the quote quality guide, "},{"type":"text","text":"Try this draft","marks":[{"type":"bold"}]},{"type":"text","text":" runs the live version and your draft on the same sample and shows what changed: what both found, and what only one did. The extraction guide is tried on a source; the quote quality guide on a theme, where each clip can be played. Nothing is added to any project, and results are kept for 14 days and are visible only to you. The other prompts do not have a trial yet."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Publish and roll back"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Publish… asks for a one-line note about what changed, then makes the draft the live version for every project."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"History lists earlier versions with the share of data points, themes or clips people accepted. Make live again moves an earlier version back into use. Nothing is deleted."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-14-sourcework-suggested-quotes',
  p_tool_key => 'transcription',
  p_released_on => '2026-10-14',
  p_title => 'Sourcework: suggested quotes',
  p_guide_slugs => array['sourcework-suggested-quotes', 'sourcework-themes', 'sourcework-research-prompts'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sourcework themes can now suggest quotes. Open an accepted theme and choose Suggest quotes: the model reads the theme’s evidence, supporting and complicating, and the transcript around it, and proposes the clips that would work best on air, each with a one-line reason and a tier. Play each as it will cut, trim it if you like, then accept it as an excerpt or reject it. A theme’s page now lists its excerpts, and a data point shows the excerpt that exemplifies it. Editors can tune what makes a clip work on air under Research prompts, and try a draft of it on a theme first."}]}]}$body$
);
